def constellation():
 rng=random.Random(24)
 pts=[]
 centers=[(160,120),(350,148),(255,300)]
 colors=['#fb9d70','#86c9b8','#b4a6ea']
 for k,(cx,cy) in enumerate(centers):
  pts.extend((min(455,max(30,cx+rng.gauss(0,38))),min(355,max(35,cy+rng.gauss(0,31))),k) for _ in range(32))
 svg='<svg viewBox="0 0 490 400" class="constellation" role="img" aria-label="Illustrative scatter plot of three groups of data points"><defs><pattern id="grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M 35 0 L 0 0 0 35" fill="none" stroke="currentColor" stroke-opacity=".075"/></pattern></defs><rect width="490" height="400" fill="url(#grid)"/>'
 for i,(x,y,k) in enumerate(pts):
  svg+=f'<circle cx="{x:.1f}" cy="{y:.1f}" r="{2.4+(i%3)*.55}" fill="{colors[k]}" opacity="{.35+(i%5)*.12}"/>'
 for i,(x,y) in enumerate(centers):
  svg+=f'<circle cx="{x}" cy="{y}" r="53" fill="none" stroke="{colors[i]}" stroke-opacity=".2" stroke-dasharray="3 5"/><path d="M{x-7} {y}h14 M{x} {y-7}v14" stroke="{colors[i]}" stroke-width="2"/>'
 return svg+'</svg>'

